) AS (
  VALUES 
    (697::BIGINT, 'El profe deja trabajos para los cuales no da la rúbrica, las instrucciones de las tareas no son para nada claras y su método de enseñanza es pasar lo que dice una presentación que no comparte con los estudiantes. Al menos deja algunos libros pero es material muy poco ortodoxo de utilizar.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'fcfc34ebf0a9ffb7565805869e12e069dfb398acfd54d01b5dc42f8ea392ded6'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'Pésimo profesor, no debería estar enseñandole a nadie. Antojadizo, pequeño y miserable.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2026-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'b914d315c5b38e7f03a7fce12015f9531293ed13d4e27b638ee75f7ff89eb1c9'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'El profesor se pasa quejando de su familia en lugar de dar las clases, las clases son leer presentaciones y no las pasa. En las evaluaciones el profesor no envía rúbricas y se las saca de la manga el día de revisión. No entrega las notas a tiempo, nunca es puntual, se obsesiona con estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '59330110fce54205d7fb1d064de04c80eca350e5e351a10180e87e325ed13f7e'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'La asistente del profe califica como la mierda, cree que el mundo gira alrededor de ella, ni el profe evalua tan rudo como esa guila, las cosas si no se hacen como ella quiere, no funciona nada.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, '0c2069ceeea7a9e6fab9a58206d310354534aaaaa17b249a49c9de7b13487348'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'Las clases son vacilonas pero el curso es UNA MIERDA, Marco cae bien la verdad pero el curso quita mas tiempo que datos i y ii juntos'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-12-13T00:00:00+00:00'::TIMESTAMPTZ, '4541b0b204d7430b5299696283d3778a298d429062c463fbd55f48b29a956554'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'Es un curso que no debería ni existir, muy innecesario. Marco no es mala persona, pero como profe no lo veo tan bien, las clases TODAS son presenciales. pasa hablando mal de la esposa y los hijos, siempre hay algo en las defensas que no le cuadra, altanero, casi no se aprende nada útil. Curso pesado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '5cf41098ad8ba7924d30fffd2c9965d620e59528124bf16b6e6b11a80244a9f7'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'Es un buen profesor, realmente se preocupa porque los estudiantes entiendan bien la materia. Almenos en el caso de BD las clases son mas amenas y la materia mucho mas interesante. Brinda bastante apoyo y califica de manera justa :D'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'cb601037157fabfa4960e3b19783cdc171213488a2e8d60583f67fc83cc8af7c'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Marco, el villano de una historia mal contada. Me gustó mucho cómo enseña el curso de Bases. Se nota que a diferencia de Paradigmas, si le gusta dar este curso. Lo único que le resto es que nunca sube los PDFs, y en cada defensa de proyecto hay algo nuevo que no le cuadra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'e7a9bfdc7a635d61d59011db72bb289902ea616464a246234d030ff6c5641126'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'No es el peor profe que he tenido. Alguno de los comentarios acá lo vendían como un demonio. Pero como persona, la verdad es que no cae mal. Eso si, no es un buen profe. O al menos, deja mucho que desear. La clave para pasar?Consiga buen grupo, encuentre los proyectos en repos y encomiéndese a Dios'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, '0df009601327fa5b349d5cad483249d96004a295b9b6988fce27c0acdb2902a3'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'Si usted es muy autodidacta tiene suerte porque solo llega a leer presentaciones y califica como si su clase fuera más que eso. Lástima que es el único que da este curso pero no queda de otra que llevar con él. Y si es mujer prepárese porque es demasiado machista.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2024-02-02T00:00:00+00:00'::TIMESTAMPTZ, '6b742c2b9fed3d28ae84597eecbf0cea5a109c404ab1d42801bf3c884e6e2b67'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'Creo que no está tan mal, es verdad lo de las presentaciones recicladas pero eso es normal en CE. Eso sí, no aporta mucho más de lo que viene en esas presentaciones. Dependiendo del día puede evaluar binario y otros días más chill. En algunas ocasiones extiende la fecha de entrega de los trabajos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, '13a937faa8be14022b7ad018ea68851c2d4b5e49156dad7735eef959177c91af'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'Clases aburridas y confusas, presentaciones recicladas. Eso sí, creo que el profe no es tan malo como se dice, si te puede ayudar te ayuda.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '0d9fcd9c91228fd98aead8ee412abec8678fc9045e58aa9ab277a4ca373fdef8'::TEXT, ARRAY[2966]::BIGINT[]),
    (697::BIGINT, 'No respeta el tiempo de los estudiantes. No es claro con sus indicaciones y después tampoco indica sus expectativas por lo que penaliza si no se alinea a estas. No dudo de su conocimiento, pero es difícil aprender cuando solo lee de presentaciones recicladas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2023-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5373dc1dfe094caf9cf81f7d83ae2816d60aaf68edbf07f3ad1f7b2b223c4a85'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Si el profe lee esto, ojalá haga las clases más prácticas, y con tecnologías o ejemplos actualizados cuando sea posible. Mucho de lo que se dice aquí tiene su parte de verdad, pero el profe no es malo, es solo que el curso no está planteado como debería.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-28T00:00:00+00:00'::TIMESTAMPTZ, '07e288fb42707fbe5f8c55b14ea1a5293fd98dc1bd6d083c3782f7d890544dc4'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'El curso por si solo ya es pesado, se debe esforzar mucho y tener un buen equipo de trabajo. El profesor llega a leer las presentaciones, las defensas es un dolor, dependiendo del ánimo que ande él así le va a ir. Siempre se saca puntos de la manga y cosas que no están en la rúbrica para bajar punto'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e10c33f1ed9cf5b1564ba00c1e602f8c199722aef10c710e54cc41c4600e873e'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Las clases son malas solo lee las presentaciones cuando no está hablando de su vida. Los proyectos SIEMRPE se saca alguna rúbrica o punto que no estaba por ninguna parte para bajarle puntos. No es explícitamente un cp con el estudiante pero aveces hace comentarios y actitudes que rozan la línea.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '690cf64dafba6493bb421df75495f982a3e55e6519602d4190baa065b4e8ca0c'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Solo lee las presentaciones y hace muchos comentarios fuera de lugar creyendo que son "graciosos". En las tareas (proyectos) evalúa lo que le da la gana y a veces baja puntos por cosas poco relevantes del trabajo. Básicamente se lleva con él porque no hay otra opción.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6ddc13342aef3fe023188870ace6212d92bba54b11f65b146ca5b774a01ad738'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'En las clases pasa la mitad hablando de su vida y experiencias de vida. Las evaluaciones es sumamente cerrado y dependiendo del humor puede ser has'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'cc3d26a7138fddc1b5bfb0fbc25474b937bbf7c26574e2915908f96f9e37f8fa'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'El profe en realidad es buena nota; pero no esperes que sea claro y califique de forma correcta los trabajos, en algunos casos le importa más una tontería que la correcta respuesta al problema planteado (respecto a las tareas). Lee los libros para los dos primeros lenguajes y así all good'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-03-29T00:00:00+00:00'::TIMESTAMPTZ, '043746af9d45776240b5cd494b7e1ec186de9eabb7928b1a531669d0f3a75303'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Muy malo. En clases solo lee las presentaciones. En los proyectos evalúa lo que le da la gana y no respeta la rúbrica. Es increíblemente cerrado, no se puede negociar nada con él y cree que siempre tiene la razón. Además suele hacer comentarios machistas y misóginos en las clases.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'd49cb47ddde8536fffb94b32e6e538d4e3e699a020f31b6180a9f68409bd4bf7'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Demasiado mediocre y se cree la última coca en el desierto, sus clases son una pérdida del tiempo y la forma en que evalua se basa en si le gusta o no, nunca da una rúbrica y se saca cosas de la manga. Ojalá el tec contrate a alguien mejor para dar esta materia.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '9ffff4a12de198691e047686310c88c04d4aa6107733f7bf62765cb203ea820e'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Regular, tiene sus cosas malas y sus cosas buenas, las revisiones de proyectos son muy estrictas, procure llevar todo preparado. Fuera de los proyectos, el resto de evaluaciones son bastante faciles. En las clases habla mucha paja a veces. No es lo mejor, pero hay muchisimo peores.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '30308480cd64153ec78f93e5a8b3c631731043190f672f281efc5730b01221d1'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Repitiendo un poco: Las clases son una pérdida de tiempo, sus criterios para calificar los proyectos son ridículos, sumamente vago. Si a uno le interesan un poco los temas uno ya va a saber más que lo que el profe le pueda enseñar.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '5344423d6ef26a76ced310082c5821e2f6d0f72558cd1277dc46cf57d9f7be6f'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Mediocre, intenta ser un buen profe pero le falta muchísimo, super irresponsable con las revisiones de los entregables, tieso a más no poder si se le pide tiempo extra, las clases son un bostezo y no sirven para nada, vealo como última opción'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas']::TEXT[], '2021-11-07T00:00:00+00:00'::TIMESTAMPTZ, '15f4b15becbd5388d7fd277777981f1c5f9961cfa504a5eca357d6cd68813a28'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'db290e9ff597c05b139e481b9ca828d7aca04fe8d494f16e02d8912c029c4dc6'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-18T00:00:00+00:00'::TIMESTAMPTZ, '5d6476593d5cefa33189dfc0fee13b82af18c4cff1f60ca7e2fdeb02cb769cf6'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Un profesor sumamente mediocre, las clases son una pérdida de tiempo, sus criterios para calificar los proyectos son ridículos, sumamente vago e irresponsable. Es una persona incapaz de reconocer sus errores y debilidades'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-17T00:00:00+00:00'::TIMESTAMPTZ, '0eac63dc68818ef6c0c864aeb682492801c2e39a69e894b2fe4f626a64576b19'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'La materia ya está mal estructurada de todas maneras, pero a pesar de eso creo que el profe se acomoda bien con todo, trata de ser comprensible con las situaciones y creo que enseña lo que puede'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '76e0aead5f2c88313db594c53e6b9bc45d1f959c970a1e180722f68932712ed7'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'El profe posiblemente sea un dementor, ya que me quito las ganas que tenia al curso e incluso la carrera. El profe sabe menos que uno con respecto a los lenguajes y eso que ha dado el curso varios años. Las clases son eternas y aburridas, pero trata de ser buena gente.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-04T00:00:00+00:00'::TIMESTAMPTZ, '814561aca528459e57865fa8fb16e3d446fb136592175cec6514d57549318244'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'El profe esta demasiado perdido con respecto a los temas de curso y la carrera en general, en realidad no esta capacitado para dar clases en la carrera, creo que un puesto como profe de informatica en un cole le quedaria bien'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2021-05-04T00:00:00+00:00'::TIMESTAMPTZ, '768c8a6919e186b7bd059bea549f8b9802f9e1a290d19a956eba85e729f24527'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Me sorprende que hablen tan mal de él, I mean, no es el mejor profesor del área, ni mucho menos, pero a nivel general me parece que se preocupa por lxs estudiantes, está abierto a ayudar y a recibir cualquier consulta, y es buena nota. El curso está mal diseñado pero no es culpa de él'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-04-29T00:00:00+00:00'::TIMESTAMPTZ, 'f2f84d50bed5f788c402ccc5f6cf243f44c5de58b535a608e44c660578215009'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Un profesor sumamente ignorante con respecto a la mayoría de los temas del curso. Proyecto inentendibles, con mala estructura, especificaciones ambiguas. Se contradice como si fuera un deporte. Es cerrado al feedback y se ofende cuando se le señalan sus errores.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-24T00:00:00+00:00'::TIMESTAMPTZ, '11cf4007b76cda704cc722bf3e66fc6ea5534947e6fe388be8f237b2e25e420f'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Es muy paciente, le importa que el estudiante aprenda y aunque lee mucho de las presentaciones da buenos ejemplos cuando se le pregunta.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-03-01T00:00:00+00:00'::TIMESTAMPTZ, 'bc18a23ec614fae6ee5f73fcea0832e2339165e0587fe0efe3760d5d1c80547d'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Llevo menos de dos semanas en el curso y ya es prácticamente la peor experiencia que he tenido en cualquier otro código CE. No es difícil ni pesado ni otras ideas que puedan tener, sino que el "profesor" lo hace un circo insensato. Otra razón más por la cual me arrepiento cada vez más de la carrera.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-27T00:00:00+00:00'::TIMESTAMPTZ, '3ed272c4dd2fdf1191542ec0fc4ed71e1127305de5a0df264a780f2baaab0c66'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Una persona bastante chill, en general. Como profesor, podría tener más orden y en las defensas evalua aspectos que, aunque no los mencionó en la especificación, para su quinto semestre debería esperarlos. Ej: presentar un .exe, no una clase ejecutable'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'b3cf9f0e983bf811184ed2d1e6a168ce7369077cf7bc56760ab5fb0f3abc3ebf'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Se saca aspectos de evaluación de la nada al revisar los proyectos, las especificaciones son muy ambiguas, pésimo y confuso proceso de evaluación.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '99941012008b1149a8fa46c20d694496d2e8363a6cee33bc62756eea6b6a1e52'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Yo no entiendo el criterio que utiliza para revisar las progras, de último momento se inventa lo que va a evaluar y si algo no le gusta ya no hay forma de sacarle puntos. Pésimo como profesor, como persona es muy bueno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '161acebefd2b15923befd7373a7d66f92ee13787e6b4ba34b935a81fdff9b769'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Muy malo. Las especificaciones son escuetas y aunque él diga que es “a propósito” para que le pregunten, es una actitud deplorable y vergonzosa. No sabe tomar retroalimentación. Toma entre ojos a los estudiantes y arma drama innecesario en las clases. Solo lee presentaciones y explica muy poco.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '29551930f774f69c35e67dd7ce1b5535d9008d1501398d3c8384907905a6902c'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'No sabe nada de lo que está haciendo y se nota que no ha trabajado en el area. Cree que todo lo sabe y si llega alguien a contradecirlo lo agarra entre ojos, peor si es mujer, las ve con ojos extraños. Le gusta armar polémica si algo pasó mal en la progra y siempre busca a quien culpar.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-03-06T00:00:00+00:00'::TIMESTAMPTZ, '107b7b7adafe52130c42005e492220ec2fd3c34968734dd3758006547fc7691a'::TEXT, ARRAY[2967, 2970]::BIGINT[]),
    (697::BIGINT, 'En clase, realiza lectura de las presentaciones. Las especificaciones de proyecto son confusas, y en la revisión revisa cosas que no estaban descritas en la misma. Como persona es excelente, ayuda si usted lo ocupa.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'f8111d3573b3c10f9ea516ba6f007628242453dbb687bb3803e395ac357775c0'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'El mae como persona es muy tuanis. Como profesor no es tampoco tan malo, lo único es que aveces es algo confuso. En las revisiones de progra procure no hablar nada que no sea necesario acerca de su trabajo ya que el mae le puede reclamar por cosas que él tan siquiera pidió en el trabajo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '18e92ee13d2142b7eff9580698b330198504dbee200cdc4b380196432be23e37'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Que se puede decir de este profe, si vas a llevar Bases te toca este o Raúl, tendrías que ver que grupo se llena primero si tenes el privilegio de escoger. No es mala persona, pero como profe creo que se desubica muy fácil en el sentido académico.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd5964a02d0d7b3ea8944afdce52d4f0d73fd1a3c8d9d55864bf4b1e9241cba47'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Las clases son brutalmente aburridas. Siempre llega muy intenso a las clases. Nunca especifica bien que es lo que quiere y se saca especificaciones de la manga en las revisiones.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '65d67a28e2425ed977bd5f5fe7ee97e771235cdf35b662f585dfb3ca56a63caa'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'En general es bueno. Se pone muy intenso en clases y en las revisiones de proyectos, se saca cosas no establecidas desde antes.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'dc610f29bb0dce5123a78f6c1feb56374c1edb3a348818e295d9fab92b2c622f'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'El profe es muy buena nota. Deja lecturas para las clases, pero al final de cuentas es para no hacer la clase aburrida y aprender. Me sorprende que hablen tan mal de él, porque sí se interesa por el estudiante y es muy abierto al feedback.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2019-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'c291ac6aae318c22f7d477836c81c33649b62b6da9df3997deaa4bae2ffb6550'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Los va a poner a leer los libros de lenguajes, para llegar a repetir la misma cosa en diapositivas. Deja una progra y llega a calificar cosas que nunca fueron especificadas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2019-04-02T00:00:00+00:00'::TIMESTAMPTZ, '17e7b63fc97d12d42b269f12b39dd0f1ff1354753d612d7b8813a0eff6821934'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Toca innecesariamente el hombro de los estudiantes (la garrita Rivera ). Su forma de calificar es confusa y no tiene dominio claro de los temas. Debe actualizar sus clases y poner mejores proyectos y menos aburridos. (Repite el mismo proyecto)'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '42738a826fad604e68c4533705e1f5f360dc5adb075d81e87caf672d53e9e026'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Es bueno y buena gente. Con los proyectos es muy estricto y se saca cosas de la manga en la revisión'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'c75f1afb302b13faba9488006f515998bdc9d00342bab23c0dc55db8ec8f006e'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'El mae no es malo, es buena nota. Las clases sí son aburridas a veces, pero el mae hace buenos ejemplos y aparte da chance de terminar los bretes en la casa y enviárselos por correo. Aparte, no hay otro profe que de el curso jaja'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '0686def8cd7d9d9b161f3eb631db8c6a034743e8e299a4c92ad12097ebb06d24'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'Clases mortalmente aburridas, solo lee las presentaciones, deja proyectos fáciles pero largos y aburridos, hace examenes con preguntas que el mismo no puede contestar, no sabe mucho de programación y no cumple con los puntos extra que promete.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '641aeaa696d7226967e0607f9e4120b182d821b9a3c8b8d17241e418c59da58e'::TEXT, ARRAY[2964, 2981]::BIGINT[]),
    (697::BIGINT, 'Probablemente el peor profesor de la carrera. Sí, así de terrible es. Es evidente que no sabe nada de muchas cosas, se pone en demasiadas estupideces, pone progras que ocupan demasiado tiempo y ni él podría hacer.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2018-06-09T00:00:00+00:00'::TIMESTAMPTZ, '16d3303d59dde55ee014415511700c32b0235667b4b99cd42a9b0276fb5bdeb8'::TEXT, ARRAY[2967]::BIGINT[]),
    (697::BIGINT, 'El profe explica bien e intenta aprovechar las clases al máximo. El curso es tranquilo pero a final de semestre deja de todo. Así que es bueno planificar bien con respeto a las otras materias cursadas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '1b6e271df121e1cc2797cf0092195ec7be97a0b9ce69d2bb47949bcd200252a2'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Solo lee presentaciones, clase bastante aburrida, es poco flexible si se necesita de mas tiempo para un proyecto y es casi imposible intentar convencerlo de algo. Deja proyectos super repetitivos y aburridos, eso si, muy fáciles.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-11T00:00:00+00:00'::TIMESTAMPTZ, '583b53733b0c08daef18dee14c380573b0408fe87dc378d95fbed549a5e1f7f6'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'En general es buen profe explica y trata de ayudar, lo malo es que deja todo para ultimo en cuanto a evaluaciones y al final de semestre se complica un poco, revisa suave los proyectos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'cb004327916c077910602462c7608b1c0d925a44cc947cbc731e0ea334fb1b8e'::TEXT, ARRAY[2970]::BIGINT[]),
    (697::BIGINT, 'Al inicio del semestre muy comprensivo y atiende dudas al instante; conforme se acerca el final de semestre el se convierte, no da retroalimentacion de los trabajos, deja todo para lo ultimo y deja demasiadas lecturas al mismo tiempo. Al final pasa pero casi no se aprende.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '843d568c8c89b5a310d0b7bb0c3dd47e4eda2c49556dd4fad88fe71cad593a66'::TEXT, ARRAY[2964]::BIGINT[]),
    (697::BIGINT, 'No metan con el, Una perdida total, el curso Difícil y el mae lo hace el doble, es llevarlo solo pues solo se lleva pero con el es a la deriva, pasa las presentaciones rápido, llega tarde. que triste que existan profesores en el Tec asi.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-04-01T00:00:00+00:00'::TIMESTAMPTZ, '58a44a051ff10f74a057dd0a8fa6e49947c78cec1a57cb835b7ed43e8649f5ec'::TEXT, ARRAY[2962]::BIGINT[]),
    (697::BIGINT, 'El mae no sabe mucho, batea mucho, califica cosas tontas y mil veces, los proyectos son demasiado repetitivos casi que se siente como hacer la misma progra 3 veces. Pero es MUY fácil'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '3ff85085c83d1e57a2b6e5b4a9cfe8bf22d397d25629a010d29c927836f0ceeb'::TEXT, ARRAY[2970]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
